-- Checklista projektering: HECO:s checklista (Checklista projektering.docx) omarbetad till avsnitt.
-- Rader som börjar med "## " är avsnittsrubriker. Mallen kan ändras i appen (Spara som mall).
INSERT INTO kontrollmall ("Id", "Typ", "Namn", "Beskrivning", "Punkter", "AndradAv") VALUES (
  'c81fa8c4-f96b-5e3d-8336-1e32e2898770', 'projektering', 'Checklista projektering',
  'Egenkontroll under projekteringen: underlag, komponenter, PLC och apparatskåp, material och miljö, krav, samordning med VE, RE, EE, KE och BE samt leverans och granskning. Avsnitt som inte berör projektet markeras Ej aktuellt.',
  '["## Start och underlag", "Status på handlingar (ritningar) från A, VE, RE och övriga entreprenörer är avstämd.", "Dokumentmallar är framtagna: handlingsförteckning, yttre komponentförteckning, funktionsbeskrivningar och typrum.", "Beteckningsstandard är bestämd och kundens standard och krav är inhämtade.", "Principer för styrning i rum (typrumsbeskrivning) är bestämda.", "Teknisk beskrivning och funktionsbeskrivning för anläggningen är framtagna.", "Gränsdragningslista finns eller är framtagen.", "Principer från andra discipliner är granskade (.8-scheman, luft och rör).", "Frågorna i frågeställningslistan är utredda.", "## Komponenter och placering", "Komponenterna är utprickade och den yttre komponentförteckningen är ifylld.", "Komponenterna är korrekt namnsatta, med rätt suffix om kunden kräver det.", "Utrymme för apparatskåp, apparatlådor och annan utrustning är samordnat.", "Kanalisation för rumsgivare, schakt, övergångar och fasta gipstak är löst (kan EE hjälpa?).", "Modulbeläggning och I/O-lista är framtagna.", "## PLC och apparatskåp", "PLC/DUC är dimensionerad för anläggningen.", "PLC/DUC klarar kommunikationskraven (Modbus, OPC, ADS m.m.).", "Kundens krav på programmeringsstandard är uppfyllda.", "Antal apparatskåp och apparatlådor är fastställt.", "Skåpens storlek är kontrollerad och platsen är angiven på ritningar och modeller.", "Effektlaster är angivna för dimensionering av matning.", "Effektberäkningen är skickad till EE.", "Kundens särskilda krav på apparatskåp är beaktade.", "Konstruktionsunderlag är skickat till skåpsleverantören.", "## Material och miljö", "Materialspecifikation är utförd.", "Materialet uppfyller kraven i BBR kap. 2:1.", "Materialet är valt utifrån kvalitet, miljö och pris.", "Leveranstiderna för materialet är kontrollerade.", "Eventuella krav på Svanenmärkning är uppfyllda.", "Eventuella krav i Miljöbyggnad är beaktade.", "Vid Sunda Hus: materialet finns listat i databasen.", "Egenkontrollen i miljöplanen är ifylld.", "Eventuella kemikalier i projektet är redovisade.", "BBR kap. 6 Miljö och hälsa uppfylls.", "Återbruk är beaktat.", "## Krav och mängder", "Alla kundspecifika krav är efterfrågade och uppfyllda.", "Särskilda krav i rambeskrivningen är beaktade.", "Mängderna är kontrollerade mot ramhandlingen.", "Mängderna är kontrollerade mot offert eller anbud.", "Lösningen för HMI/SCADA är specificerad.", "## Funktioner att ta ställning till", "Energioptimering och energifunktioner är bestämda.", "Rumsgivare (antal, typ och placering) är bestämda.", "Mätinsamlingssystem är bestämt.", "Behovet av soleffektsgivare är utrett.", "Behovet av fuktgivare för daggpunkt är utrett.", "## Säkerhet och brand", "Riskanalysen är ifylld och inskickad.", "Teoretisk samordnad funktionskontroll är genomförd enligt BBR kap. 5 eller projektets brandskyddsbeskrivning.", "## Ventilation (VE)", "Genomgång SE–VE är genomförd.", "Särmöte med VE om teknisk lösning är hållet före granskningshandling.", "Principritningarna är upprättade och alla komponenter finns med.", "Spjäll och komponenter är utritade på planritningarna.", "Beteckningarna på yttre komponenter (FF, ST m.fl.) är avstämda.", "Antalet brandspjäll är fastställt (ange antal i kommentaren).", "Det är klarlagt vilka spjäll VE levererar.", "Styrning vid brand och rökevakuering är bestämd.", "Styrning vid brand i aggregat (rökdetektor) är bestämd.", "Effektuppgifterna är inhämtade.", "Detaljlösningen för VAV är bestämd.", "Eventuella enhetsaggregat är utredda.", "Förregling mot ozon i kök är utredd.", "Luftflödesprotokoll från ventilationskonsulten finns (zoner och luftflöden).", "## Rör (RE)", "Genomgång SE–RE är genomförd.", "Särmöte med RE om teknisk lösning är hållet före granskningshandling.", "Principritningarna är upprättade och beteckningarna är införda.", "Komponenterna på principerna har rätt beteckningar.", "Effektuppgifterna är inhämtade.", "kv-värdena är införda.", "Typen av M-bus-mätare är bestämd.", "Det är klarlagt vem som levererar lösa ventiler och ställdon.", "Golvvärmen är utredd (ska vi styra något?).", "Fläktluftvärmare och ridåvärmare är utredda.", "Pumpgropar och spillvattenpumpning är utredda.", "Tryckstegring för kallvatten är utredd.", "## El (EE)", "Genomgång SE–EE är genomförd.", "Särmöte med EE om teknisk lösning är hållet före granskningshandling.", "Placeringen av centralt brandlarm är känd.", "Nätverksuttag finns där de behövs.", "Plats för SE i elnischer är avstämd.", "Det är bestämt vilka larm SE ska ta in och hur.", "Larm är utredda: överspänningsskydd, jordfelsbrytare, reservkraft, nödljus och takavvattning/snösmältning.", "Signal för pålarmad byggnad (inbrottslarm) är utredd.", "Det är bestämt om SE ska styra tidkanaler och skymningsrelä.", "Det är klarlagt vilka mätare som ska tas in och vem som drar kablaget.", "Styrning och matning av brandfläktar är bestämd.", "Eventuellt KNX-system är utrett.", "EE:s kanalisation i rum är avstämd.", "Vid rumsreglering: EE:s avlämningspunkter för transformatorer är bestämda.", "Information från solceller är utredd.", "Kanalisation för utegivare är klar och placeringen är överlämnad.", "## Kyla (KE)", "Genomgång SE–KE är genomförd.", "Styrningen av kylmaskinen är bestämd.", "Kommunikationen är bestämd (Modbus RTU eller TCP) och modbusprotokoll för maskinerna finns.", "Plintar för förregling och larm är bestämda.", "Komponenter och larm i kyl- och frysrum är utredda.", "## Bygg (BE)", "Genomgång SE–BE är genomförd.", "Fettavskiljare: larm och matning är utredda.", "Styrning av solavskärmning och vädringsluckor är utredd.", "Övervakning av rökluckor är utredd.", "## Leverans och granskning", "Driftkort är upprättade.", "Mätplan för volym- och energimätare är upprättad.", "Installationsritningar för komponenter och funktioner är upprättade.", "Samtliga handlingar är granskade internt.", "Samtliga handlingar är granskade av beställaren.", "Samtliga handlingar är granskade av slutkunden.", "Samtliga handlingar ligger på företagets filserver.", "Samtliga handlingar ligger på projektets portal (Ibinder, SharePoint e.d.).", "Nödvändiga handlingar ligger på slutkundens portal."]', 'Projekteringsverktyg') ON CONFLICT DO NOTHING;
